<?php declare(strict_types=1); namespace Database\Schema; use Core\Database\Schema\Blueprint; use Core\Database\Schema\SchemaDefinition; class ProductCardFeaturesSchema extends SchemaDefinition { protected string $table = 'product_card_features'; public function define(Blueprint $table): void { $table->id(); $table->foreignId('product_id')->index(); $table->foreignId('preset_id')->nullable()->index(); $table->string_50('icon_key')->default('spec'); $table->integer('sort_order')->default(0); $table->timestamps(); $table->foreign('product_id')->references('id')->on('products')->onDelete('CASCADE'); $table->foreign('preset_id')->references('id')->on('product_feature_presets')->onDelete('SET NULL'); } } 